import * as ec2 from "aws-cdk-lib/aws-ec2";
import { Construct } from "constructs";

/**
 * Properties for the SecurityGroups construct
 */
export interface SecurityGroupsProps {
  /**
   * The VPC where security groups will be created
   */
  vpc: ec2.IVpc;

  /**
   * Whether to create standalone mode security groups
   * @default false
   */
  isStandalone?: boolean;

  /**
   * Whether app proxy is enabled (for creating proxy-specific security groups)
   * @default false
   */
  appProxyEnabled?: boolean;
}

/**
 * Centralized security groups management for Hyperswitch infrastructure.
 * This construct creates all security groups upfront and improve maintainability.
 */
export class SecurityGroups extends Construct {
  // Core security groups
  public readonly lbSecurityGroup: ec2.SecurityGroup;
  public readonly istioInternalLbSecurityGroup: ec2.SecurityGroup;
  public readonly envoyAsgSecurityGroup: ec2.SecurityGroup;
  public readonly vpcEndpointSecurityGroup: ec2.SecurityGroup;
  public readonly grafanaIngressLbSecurityGroup: ec2.SecurityGroup;
  public readonly clusterSecurityGroup: ec2.SecurityGroup;
  public readonly externalLbSecurityGroup?: ec2.SecurityGroup;
  public readonly squidInternalLbSecurityGroup?: ec2.SecurityGroup;
  public readonly squidAsgSecurityGroup?: ec2.SecurityGroup;

  // Standalone mode security groups
  public readonly ec2SecurityGroup?: ec2.SecurityGroup;
  public readonly appAlbSecurityGroup?: ec2.SecurityGroup;
  public readonly sdkAlbSecurityGroup?: ec2.SecurityGroup;

  constructor(scope: Construct, id: string, props: SecurityGroupsProps) {
    super(scope, id);

    const { vpc, isStandalone = false, appProxyEnabled = false } = props;

    // Create core security groups that are always needed

    // 1. Load Balancer Security Group
    this.lbSecurityGroup = new ec2.SecurityGroup(this, 'LoadBalancerSG', {
      vpc: vpc,
      allowAllOutbound: false,
      securityGroupName: 'hs-loadbalancer-sg',
      description: 'Security group for load balancers',
    });

    this.lbSecurityGroup.addIngressRule(
      ec2.Peer.anyIpv4(), 
      ec2.Port.allTraffic(),
      'Allow all inbound traffic'
    );

    // 2. Istio Internal Load Balancer Security Group
    this.istioInternalLbSecurityGroup = new ec2.SecurityGroup(this, 'IstioInternalLbSG', {
      vpc: vpc,
      allowAllOutbound: false,
      description: 'Security group for Istio internal ALB - Bridge between Envoy ASG and EKS',
    });

    // 3. Envoy ASG Security Group
    this.envoyAsgSecurityGroup = new ec2.SecurityGroup(this, 'EnvoyAsgSG', {
      vpc: vpc,
      allowAllOutbound: false,
      description: 'Security group for Envoy ASG EC2 instances',
    });

    // 4. VPC Endpoint Security Group
    this.vpcEndpointSecurityGroup = new ec2.SecurityGroup(this, 'VpcEndpointSG', {
      vpc: vpc,
      allowAllOutbound: false,
      description: 'Security group for VPC interface endpoints',
    });

    // 5. Grafana Ingress Load Balancer Security Group
    this.grafanaIngressLbSecurityGroup = new ec2.SecurityGroup(this, 'GrafanaIngressLbSG', {
      vpc: vpc,
      allowAllOutbound: true,
      securityGroupName: 'grafana-ingress-lb',
      description: 'Security group for Grafana ingress load balancer',
    });

    // 6. EKS Cluster Security Group
    this.clusterSecurityGroup = new ec2.SecurityGroup(this, 'ClusterSecurityGroup', {
      vpc: vpc,
      allowAllOutbound: false,
      description: 'Security group for EKS cluster',
    });

    // Add essential outbound rules for EKS cluster
    this.clusterSecurityGroup.addEgressRule(
      ec2.Peer.anyIpv4(),
      ec2.Port.tcp(443),
      'Allow HTTPS for EKS API, ECR, S3'
    );
    this.clusterSecurityGroup.addEgressRule(
      ec2.Peer.anyIpv4(),
      ec2.Port.udp(53),
      'Allow DNS UDP'
    );
    this.clusterSecurityGroup.addEgressRule(
      ec2.Peer.anyIpv4(),
      ec2.Port.tcp(53),
      'Allow DNS TCP'
    );

    // Create app proxy security groups if enabled
    if (appProxyEnabled) {
      // External Load Balancer Security Group
      this.externalLbSecurityGroup = new ec2.SecurityGroup(this, 'ExternalLbSecurityGroup', {
        vpc: vpc,
        description: 'Security group for external ALB',
        allowAllOutbound: false,
      });

      // Squid Internal Load Balancer Security Group
      this.squidInternalLbSecurityGroup = new ec2.SecurityGroup(this, 'SquidInternalLbSecurityGroup', {
        vpc: vpc,
        description: 'Security group for Squid internal ALB',
        allowAllOutbound: false,
      });

      // Squid ASG Security Group
      this.squidAsgSecurityGroup = new ec2.SecurityGroup(this, 'SquidAsgSecurityGroup', {
        vpc: vpc,
        description: 'Security group for Squid Auto Scaling Group instances',
        allowAllOutbound: false,
      });
    }

    // Create standalone mode security groups if needed
    if (isStandalone) {
      // EC2 Security Group for standalone instances
      this.ec2SecurityGroup = new ec2.SecurityGroup(this, 'EC2SecurityGroup', {
        vpc: vpc,
        description: 'Security group for EC2 instances',
        allowAllOutbound: true,
      });

      // App ALB Security Group
      this.appAlbSecurityGroup = new ec2.SecurityGroup(this, 'AppAlbSG', {
        vpc: vpc,
        description: 'SG for App ALB',
        allowAllOutbound: true,
      });

      // SDK ALB Security Group
      this.sdkAlbSecurityGroup = new ec2.SecurityGroup(this, 'SdkAlbSG', {
        vpc: vpc,
        description: 'SG for SDK ALB',
        allowAllOutbound: true,
      });

      // Add standalone mode specific rules
      this.setupStandaloneModeRules();
    }

    // Set up basic security group rules that don't depend on other constructs
    this.setupBasicRules();

    // Set up cross-security group rules
    this.setupCrossSecurityGroupRules();

    // Set up app proxy workflow rules if enabled
    if (appProxyEnabled) {
      this.setupAppProxyWorkflowRules();
    }
  }

  /**
   * Set up basic security group rules that don't depend on other constructs
   */
  private setupBasicRules(): void {
    // Envoy ASG instance rules
    if (!this.externalLbSecurityGroup) {
      this.envoyAsgSecurityGroup.addIngressRule(
        this.lbSecurityGroup,
        ec2.Port.tcp(80),
        'Allow HTTP traffic from External ALB (legacy)'
      );
    }

    // Egress: Allow HTTPS to S3 (via VPC Gateway Endpoint)
    this.envoyAsgSecurityGroup.addEgressRule(
      ec2.Peer.anyIpv4(),
      ec2.Port.tcp(443),
      'Allow HTTPS to S3 (via VPC Gateway Endpoint)'
    );

    // Egress: Allow DNS
    this.envoyAsgSecurityGroup.addEgressRule(
      ec2.Peer.anyIpv4(),
      ec2.Port.udp(53),
      'Allow DNS UDP'
    );
    this.envoyAsgSecurityGroup.addEgressRule(
      ec2.Peer.anyIpv4(),
      ec2.Port.tcp(53),
      'Allow DNS TCP'
    );

    // VPC Endpoint Security Group rules
    // Allow HTTPS traffic from load balancer security group
    this.vpcEndpointSecurityGroup.addIngressRule(
      this.lbSecurityGroup,
      ec2.Port.tcp(443),
      'Allow HTTPS from load balancer security group'
    );
  }

  /**
   * Set up cross-security group rules
   */
  private setupCrossSecurityGroupRules(): void {
    // Istio Internal LB rules
    // Allow traffic from Envoy ASG security group
    this.istioInternalLbSecurityGroup.addIngressRule(
      this.envoyAsgSecurityGroup,
      ec2.Port.tcp(80),
      'Allow HTTP from Envoy ASG instances only'
    );

    // Envoy ASG can send traffic to Istio Internal LB
    this.envoyAsgSecurityGroup.addEgressRule(
      this.istioInternalLbSecurityGroup,
      ec2.Port.tcp(80),
      'Allow HTTP to Istio Internal LB only'
    );
  }

  /**
   * Set up standalone mode specific rules
   */
  private setupStandaloneModeRules(): void {
    if (!this.appAlbSecurityGroup || !this.sdkAlbSecurityGroup || !this.ec2SecurityGroup) {
      return;
    }

    // App ALB rules
    this.appAlbSecurityGroup.addIngressRule(
      ec2.Peer.anyIpv4(), 
      ec2.Port.tcp(80),
      'Allow HTTP from anywhere'
    );
    this.appAlbSecurityGroup.addIngressRule(
      ec2.Peer.anyIpv4(), 
      ec2.Port.tcp(9000),
      'Allow port 9000 from anywhere'
    );

    // SDK ALB rules
    this.sdkAlbSecurityGroup.addIngressRule(
      ec2.Peer.anyIpv4(), 
      ec2.Port.tcp(9090),
      'Allow port 9090 from anywhere'
    );
    this.sdkAlbSecurityGroup.addIngressRule(
      ec2.Peer.anyIpv4(), 
      ec2.Port.tcp(5252),
      'Allow port 5252 from anywhere'
    );

    // EC2 instance rules
    this.ec2SecurityGroup.addEgressRule(
      ec2.Peer.anyIpv4(),
      ec2.Port.tcp(443),
      'Allow outbound HTTPS traffic for SSM'
    );
  }

  /**
   * Add rules for EKS cluster security group after cluster is created
   * @param clusterSecurityGroup The EKS cluster security group
   * @param appProxyEnabled Whether app proxy is enabled for conditional rules
   */
  public addEksClusterRules(clusterSecurityGroup: ec2.ISecurityGroup, appProxyEnabled: boolean = false): void {
    // --- Ingress to Cluster ---
    // Allow traffic from the main and Istio load balancers to the cluster
    this.lbSecurityGroup.addEgressRule(
      clusterSecurityGroup,
      ec2.Port.allTraffic(),
      'Allow all traffic to EKS cluster'
    );
    clusterSecurityGroup.addIngressRule(
      this.lbSecurityGroup,
      ec2.Port.allTraffic(),
      'Allow all traffic from main LB'
    );

    this.istioInternalLbSecurityGroup.addEgressRule(
      clusterSecurityGroup,
      ec2.Port.tcp(80),
      'Allow HTTP to EKS cluster only'
    );
    clusterSecurityGroup.addIngressRule(
      this.istioInternalLbSecurityGroup,
      ec2.Port.tcp(80),
      'Allow HTTP from Istio Internal LB'
    );

    // --- Egress from Cluster ---
    // Conditional outbound rules based on app proxy configuration
    if (appProxyEnabled && this.squidInternalLbSecurityGroup) {
      // App proxy enabled: Allow outbound traffic to Squid proxy
      clusterSecurityGroup.addEgressRule(
        this.squidInternalLbSecurityGroup,
        ec2.Port.tcp(3128),
        'Allow outbound traffic to Squid proxy'
      );
      // And allow ingress on the squid LB from the cluster
      this.squidInternalLbSecurityGroup.addIngressRule(
        clusterSecurityGroup,
        ec2.Port.tcp(3128),
        'Allow traffic from EKS cluster security group'
      );
    } else {
      // App proxy disabled: Allow direct internet access for applications
      clusterSecurityGroup.addEgressRule(
        ec2.Peer.anyIpv4(),
        ec2.Port.tcp(80),
        'Allow HTTP to internet (direct access)'
      );
      clusterSecurityGroup.addEgressRule(
        ec2.Peer.anyIpv4(),
        ec2.Port.tcp(443),
        'Allow HTTPS to internet (direct access)'
      );
    }
  }

  /**
   * Add VPN-specific ingress rules to Grafana security group
   * @param vpnIps Array of VPN IP addresses
   */
  public addGrafanaVpnRules(vpnIps: string[]): void {
    vpnIps.forEach(ip => {
      if (ip !== "0.0.0.0/0") {
        const vpnPorts = [443, 80];
        vpnPorts.forEach(port =>
          this.grafanaIngressLbSecurityGroup.addIngressRule(
            ec2.Peer.ipv4(ip), 
            ec2.Port.tcp(port),
            `Allow port ${port} from VPN IP ${ip}`
          )
        );
      }
    });
  }

  /**
   * Add rules for VPC endpoints from private subnet CIDRs
   * @param privateSubnets Array of private subnets
   */
  public addVpcEndpointSubnetRules(privateSubnets: ec2.ISubnet[]): void {
    privateSubnets.forEach((subnet, index) => {
      this.vpcEndpointSecurityGroup.addIngressRule(
        ec2.Peer.ipv4(subnet.ipv4CidrBlock),
        ec2.Port.tcp(443),
        `Allow HTTPS from private subnet ${subnet.subnetId}`
      );
    });
  }

  /**
   * Set up app proxy workflow rules
   */
  private setupAppProxyWorkflowRules(): void {
    if (!this.externalLbSecurityGroup || !this.squidInternalLbSecurityGroup || !this.squidAsgSecurityGroup) {
      return;
    }

    // 1. CloudFront -> External LB (HTTPS/HTTP)
    this.externalLbSecurityGroup.addIngressRule(
      ec2.Peer.anyIpv4(),
      ec2.Port.tcp(80),
      'Allow HTTP from CloudFront'
    );
    this.externalLbSecurityGroup.addIngressRule(
      ec2.Peer.anyIpv4(),
      ec2.Port.tcp(443),
      'Allow HTTPS from CloudFront'
    );

    // 2. External LB -> Envoy ASG
    this.externalLbSecurityGroup.addEgressRule(
      this.envoyAsgSecurityGroup,
      ec2.Port.tcp(8080),
      'Allow traffic to Envoy ASG instances'
    );
    this.envoyAsgSecurityGroup.addIngressRule(
      this.externalLbSecurityGroup,
      ec2.Port.tcp(8080),
      'Allow traffic from External LB'
    );

    // 3. Envoy ASG -> Istio Internal LB (already configured in setupCrossSecurityGroupRules)

    // 4. Istio Internal LB -> EKS Cluster (handled in addEksClusterRules)

    // ALB health checks come from the ALB itself, not from Envoy ASG
    this.istioInternalLbSecurityGroup.addIngressRule(
      this.istioInternalLbSecurityGroup,
      ec2.Port.tcp(80),
      'Allow ALB health checks on port 80'
    );
    this.istioInternalLbSecurityGroup.addIngressRule(
      this.istioInternalLbSecurityGroup,
      ec2.Port.tcp(15021),
      'Allow ALB health checks on Istio status port 15021'
    );

    // 5. EKS Cluster -> Squid Internal LB (for outbound traffic)

    // 6. Squid Internal LB -> Squid ASG
    this.squidInternalLbSecurityGroup.addEgressRule(
      this.squidAsgSecurityGroup,
      ec2.Port.tcp(3128),
      'Allow traffic to Squid ASG instances'
    );
    this.squidAsgSecurityGroup.addIngressRule(
      this.squidInternalLbSecurityGroup,
      ec2.Port.tcp(3128),
      'Allow traffic from Squid Internal LB'
    );

    // 7. Squid ASG -> Internet (outbound traffic)
    this.squidAsgSecurityGroup.addEgressRule(
      ec2.Peer.anyIpv4(),
      ec2.Port.tcp(80),
      'Allow HTTP to internet'
    );
    this.squidAsgSecurityGroup.addEgressRule(
      ec2.Peer.anyIpv4(),
      ec2.Port.tcp(443),
      'Allow HTTPS to internet'
    );

    // Additional rules for health checks
    this.setupHealthCheckRules();
  }

  /**
   * Set up health check rules for ALBs
   */
  private setupHealthCheckRules(): void {
    if (!this.externalLbSecurityGroup || !this.squidInternalLbSecurityGroup || !this.squidAsgSecurityGroup) {
      return;
    }

    // Health check rules for External ALB
    this.externalLbSecurityGroup.addEgressRule(
      this.envoyAsgSecurityGroup,
      ec2.Port.tcp(8081), // Health check port
      'Health check to Envoy instances'
    );
    this.envoyAsgSecurityGroup.addIngressRule(
      this.externalLbSecurityGroup,
      ec2.Port.tcp(8081),
      'Health check from External LB'
    );

  }
}

import * as ec2 from "aws-cdk-lib/aws-ec2";
import { Construct } from "constructs";
import * as codebuild from "aws-cdk-lib/aws-codebuild";
import { Config } from "./config";
import * as cr from "aws-cdk-lib/custom-resources";
import { PolicyStatement } from "aws-cdk-lib/aws-iam";
import * as cdk from "aws-cdk-lib";
import * as s3 from 'aws-cdk-lib/aws-s3';
import { EksStack } from "./eks";
import { DistributionConstruct } from "./distribution"
import * as iam from "aws-cdk-lib/aws-iam";
import { readFileSync } from "fs";
import { Code, Function, Runtime } from "aws-cdk-lib/aws-lambda";

export class HyperswitchSDKStack extends Construct {
  constructor(scope: Construct, eks: EksStack, distribution: DistributionConstruct ) {
    super(scope, 'HyperswitchSDKStack');

    const sdkBuildRole = new iam.Role(scope, "sdkBucketRole", {
      assumedBy: new iam.ServicePrincipal("codebuild.amazonaws.com"),
    });

    const sdkBuildPolicy = new iam.PolicyDocument({
      statements: [
        new iam.PolicyStatement({
          actions: [
            "s3:putObject",
            "s3:getObject",
            "s3:ListBucket",
            "elasticloadbalancing:DescribeLoadBalancers",
            "elbv2:DescribeLoadBalancers",
            "cloudfront:ListDistributions"
          ],
          resources: ["*"],
        }),
      ],
    });

    sdkBuildRole.attachInlinePolicy(
      new iam.Policy(scope, "SDKBucketAccessPolicy", {
        document: sdkBuildPolicy,
      })
    );

    let sdkVersion = "0.125.0";

    const project = new codebuild.Project(scope, "HyperswitchSDK", {
      projectName: "HyperswitchSDK",
      role: sdkBuildRole,
      buildSpec: codebuild.BuildSpec.fromObject({
        version: "0.2",
        phases: {
          install: {
            commands: [
              'LB_NAME=$(aws elbv2 describe-load-balancers --query "LoadBalancers[?LoadBalancerName==\'external-lb\'].LoadBalancerName | [0]" --output text)',
              'if [ "$LB_NAME" = "None" ] || [ -z "$LB_NAME" ]; then LB_NAME="hyperswitch"; fi',
              'HOST=$(aws elbv2 describe-load-balancers --names $LB_NAME --query "LoadBalancers[0].DNSName" --output text)',
              'BACKEND_URL=$(aws cloudfront list-distributions --query "DistributionList.Items[?Origins.Items[?DomainName==\'${HOST}\']].DomainName" --output text)',
              'export ENV_BACKEND_URL="https://${BACKEND_URL}"',
              "git clone --branch v" + sdkVersion + " https://github.com/juspay/hyperswitch-web",
              "cd hyperswitch-web",
              "curl -L https://raw.githubusercontent.com/tj/n/master/bin/n -o n",
              "chmod +x n",
              "./n 18",
              "npm install",
              "npm run re:build",
            ],
          },
          build: {
            commands: "DISABLE_CSP=false ENV_SDK_URL=$envSdkUrl npm run build:sandbox",
          },
          post_build: {
            commands: [
              "aws s3 cp --recursive dist/sandbox/ s3://$sdkBucket/web/" + sdkVersion + "/",
            ],
          },
        },
      }),
      environmentVariables: {
        sdkBucket: {
          value: eks.sdkBucket.bucketName,
          type: codebuild.BuildEnvironmentVariableType.PLAINTEXT,
        },
        envSdkUrl: {
          value: "https://" + eks.sdkDistribution.distributionDomainName,
          type: codebuild.BuildEnvironmentVariableType.PLAINTEXT,
        },
      },
      environment: {
        buildImage: codebuild.LinuxBuildImage.AMAZON_LINUX_2_5,
      },
    });

    eks.sdkBucket.grantReadWrite(project);

    project.node.addDependency(eks.lokiChart); 
    project.node.addDependency(distribution.routerDistribution);

    const lambdaStartBuildCode = readFileSync('./dependencies/code_builder/start_build.py').toString();

    const triggerCodeBuildRole = new iam.Role(scope, "SdkAssetsUploadLambdaRole", {
      assumedBy: new iam.ServicePrincipal("lambda.amazonaws.com"),
    });

    const triggerCodeBuildPolicy = new iam.PolicyDocument({
      statements: [
        new iam.PolicyStatement({
          actions: [
            "codebuild:StartBuild",
          ],
          resources: [project.projectArn],
        }),
      ],
    });

    const logsPolicy = new iam.PolicyDocument({
      statements: [
        new iam.PolicyStatement({
          actions: [
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents",
          ],
          resources: ["*"],
        }),
      ],
    });

    triggerCodeBuildRole.attachInlinePolicy(
      new iam.Policy(scope, "SdkAssetsUploadLambdaPolicy", {
        document: triggerCodeBuildPolicy,
      })
    );

    triggerCodeBuildRole.attachInlinePolicy(
      new iam.Policy(scope, "SdkAssetsUploadLambdaLogsPolicy", {
        document: logsPolicy,
      })
    );

    const triggerCodeBuild = new Function(scope, "SdkAssetsUploadLambda", {
      runtime: Runtime.PYTHON_3_9,
      handler: "index.lambda_handler",
      code: Code.fromInline(lambdaStartBuildCode),
      timeout: cdk.Duration.minutes(15),
      role: triggerCodeBuildRole,
      environment: {
        PROJECT_NAME: project.projectName,
      },
    });

    const codebuildTrigger = new cdk.CustomResource(scope, "SdkAssetsUploadCR", {
      serviceToken: triggerCodeBuild.functionArn,
    });
  }
}

#!/usr/bin/env node
import "source-map-support/register";
import * as cdk from "aws-cdk-lib";
import { Configuration } from "../awsconfig";
import { Cloud, HyperswitchStack } from "../lib/hs-stack";

const app = new cdk.App();
let config = new Configuration(app).getConfig();
type AccountRegion = {
  account?: string;
  region?: string;
};
const currentAccount: AccountRegion = {
  region: process.env.CDK_DEFAULT_REGION || undefined,
  account: process.env.CDK_DEFAULT_ACCOUNT || undefined,
};

if (!process.env.CDK_DEFAULT_REGION) {
  throw Error("please do `export CDK_DEFAULT_REGION=<your region>`");
}
app.node.setContext("currentAccount", currentAccount);
new HyperswitchStack(app, config, Cloud.AWS);

import boto3
import os
import json
import urllib3

http = urllib3.PoolManager()

def send(event, context, responseStatus, responseData, physicalResourceId=None, noEcho=False, reason=None):
    responseUrl = event['ResponseURL']

    responseBody = {
        'Status': responseStatus,
        'Reason': reason or "See the details in CloudWatch Log Stream: {}".format(context.log_stream_name),
        'PhysicalResourceId': physicalResourceId or context.log_stream_name,
        'StackId': event['StackId'],
        'RequestId': event['RequestId'],
        'LogicalResourceId': event['LogicalResourceId'],
        'NoEcho': noEcho,
        'Data': responseData
    }

    json_responseBody = json.dumps(responseBody)

    print("Response body:")
    print(json_responseBody)

    headers = {
        'content-type': '',
        'content-length': str(len(json_responseBody))
    }

    try:
        response = http.request(
            'PUT', responseUrl, headers=headers, body=json_responseBody)
        print("Status code:", response.status)
        return responseBody

    except Exception as e:

        print("send(..) failed executing http.request(..):", e)
        return {}


def lambda_handler(event, context):
    # get the details from the codebuild project from the environment variables and trigger the codebuild project
    if event['RequestType'] == 'Create':
        try:
            codebuild = boto3.client('codebuild')
            response = codebuild.start_build(
                projectName=os.environ['PROJECT_NAME'],
            )
            send(event, context, "SUCCESS", {"message": "CodeBuild project started"})
        except Exception as e:
            send(event, context, "FAILED", {"message": str(e)})
    else:
        send(event, context, "SUCCESS", {"message": "No action required"})

    return '{ "status": 200, "message": "success" }'

import * as ec2 from 'aws-cdk-lib/aws-ec2';
import * as elasticache from 'aws-cdk-lib/aws-elasticache';
import { Construct } from "constructs";
import { Config } from './config';
import { SecurityGroup } from 'aws-cdk-lib/aws-ec2';

export class ElasticacheStack {
    cluster: elasticache.CfnCacheCluster;
    sg: ec2.SecurityGroup;
    constructor(scope: Construct, config: Config, vpc: ec2.Vpc) {
        const elasticache_security_group = new SecurityGroup(scope, "Hyperswitch-elasticache-SG", {
            securityGroupName: "Hyperswitch-elasticache-SG",
            vpc: vpc,
          });

          this.sg = elasticache_security_group;

        const subnetgroup = new elasticache.CfnSubnetGroup(scope, 'HSSubnetGroup', {
            description: 'Hyperswitch Elasticache subnet group',
            subnetIds: vpc.publicSubnets.map((subnet) => subnet.subnetId),
        });
        const cluster = new elasticache.CfnCacheCluster(scope, 'HSCacheCluster', {
            clusterName: 'hs-elasticache',
            cacheNodeType: 'cache.t3.micro',
            engine: 'redis',
            numCacheNodes: 1,
            cacheSubnetGroupName: subnetgroup.ref,
            vpcSecurityGroupIds: [elasticache_security_group.securityGroupId], // create a security group for the cache cluster
        });
        this.cluster = cluster;
    }
}

import * as ec2 from "aws-cdk-lib/aws-ec2";
import { Config } from "./lib/aws/config";
import { Construct } from "constructs";
import { readFileSync, existsSync } from "fs";

export class Configuration {
  config: Config;
  constructor(scope: Construct) {
    let db_pass = scope.node.tryGetContext('db_pass') || "dbpassword";
    let admin_api_key = scope.node.tryGetContext('admin_api_key') || "test_admin"
    let master_key = scope.node.tryGetContext('master_enc_key')
    let tls_key_exists = existsSync("./rsa_sha256_key.pem");
    let tls_cert_exists = existsSync("./rsa_sha256_cert.pem");
    let ca_cert_exists = existsSync("./ca_cert.pem");
    let client_cert_exists = existsSync("./client_hyperswitch.pem");
    let config: Config = {
      stack: {
        name: "hyperswitch",
        region: process.env.CDK_DEFAULT_REGION || "us-east-1"
      },
      vpc: {
        name: "hyperswitch-vpc",
        maxAzs: 2,
      },
      subnet: {
        public: {
          name: "public"
        },
        dmz: {
          name: "private"
        }
      },
      keymanager: {
        enabled: scope.node.tryGetContext('keymanager_enabled') || false,
        name: "keymanager",
        db_user: "keymanager_db_user",
        db_pass: "pass1234",
        tls_key: tls_key_exists ? readFileSync("./rsa_sha256_key.pem").toString() : "", 
        tls_cert: tls_cert_exists ? readFileSync("./rsa_sha256_cert.pem").toString() : "", 
        ca_cert: ca_cert_exists ? readFileSync("./ca_cert.pem").toString() : "",
        client_cert: client_cert_exists ? readFileSync("./client_hyperswitch.pem").toString() : "",
        access_token: scope.node.tryGetContext('keymanager_access_token') || "secret123",
        hash_context: scope.node.tryGetContext('keymanager_hash_context') || "keymanager:hyperswitch",
      },
      extra_subnets: [],
      rds: {
        port: 5432,
        db_user: "db_user",
        db_name: "hyperswitch",
        password: db_pass,
        writer_instance_class: ec2.InstanceClass.T3,
        writer_instance_size: ec2.InstanceSize.MEDIUM,
        reader_instance_class: ec2.InstanceClass.T3,
        reader_instance_size: ec2.InstanceSize.MEDIUM,
      },
      hyperswitch_ec2: {
        id: "hyperswitch",
        admin_api_key: admin_api_key,
        redis_host: "",
        db_host: "",
        master_enc_key: master_key
      },
      locker: {
        master_key: scope.node.tryGetContext('master_key'),
        db_user: "lockeruser",
        db_pass: scope.node.tryGetContext('locker_pass')

      },
      tags: {}
    }
    this.config = config;
  }
  getConfig() {
    return this.config;
  }
}
